package com.wos.giftredeemer;
import android.app.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.JSONObject;import java.text.*;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends Activity{
 private AppDatabase db;private FrameLayout content;private TextView title,subtitle;private View bottomNav,accountsButton;private final ExecutorService worker=Executors.newSingleThreadExecutor();private GiftCodeScraper scraper;private volatile boolean busy,cancelRequested;private String currentTab="REDEEM";
 private int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}private TextView tv(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(getColor(R.color.ink));t.setLineSpacing(0,1.08f);t.setPadding(0,dp(2),0,dp(2));return t;}private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(14);b.setTextColor(getColor(R.color.ink));b.setMinHeight(dp(48));b.setMinimumWidth(0);b.setPadding(dp(14),0,dp(14),0);b.setSingleLine(true);b.setEllipsize(android.text.TextUtils.TruncateAt.END);boolean primary=s.startsWith("Check")||s.startsWith("Redeem")||s.startsWith("Start")||s.startsWith("Add Account")||s.startsWith("Try Again");if(modernTheme()){b.setBackgroundResource(primary?R.drawable.primary_button:R.drawable.secondary_button);if(primary)b.setTextColor(android.graphics.Color.WHITE);}else{b.setBackgroundResource(R.drawable.button_classic);b.setTextColor(getColor(R.color.ink));b.setTypeface(android.graphics.Typeface.MONOSPACE,android.graphics.Typeface.NORMAL);}return b;}private LinearLayout body(){LinearLayout b=new LinearLayout(this);b.setOrientation(LinearLayout.VERTICAL);b.setPadding(dp(16),dp(16),dp(16),dp(24));return b;}private LinearLayout.LayoutParams compactLp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(4),dp(4),dp(4),dp(4));return p;}private LinearLayout.LayoutParams stackedLp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));return p;}private void addStacked(LinearLayout parent,View child){parent.addView(child,stackedLp());}private LinearLayout card(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(modernTheme()?dp(16):dp(12),modernTheme()?dp(16):dp(12),modernTheme()?dp(16):dp(12),modernTheme()?dp(16):dp(12));c.setBackgroundResource(modernTheme()?R.drawable.card_modern:R.drawable.card_classic);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,dp(16));c.setLayoutParams(p);return c;}private ScrollView page(LinearLayout b){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.addView(b);return s;}private void setPage(View v){content.removeAllViews();content.addView(v,new FrameLayout.LayoutParams(-1,-1));}private void heading(LinearLayout b,String h,String d){TextView x=tv(h,19);if(modernTheme())x.setTypeface(null,1);else x.setTypeface(android.graphics.Typeface.MONOSPACE,android.graphics.Typeface.BOLD);b.addView(x);if(d!=null){TextView y=tv(d,13);y.setTextColor(getColor(R.color.muted));b.addView(y);}}
 private String themeChoice(){return getPreferences(0).getString("theme","Modern UI");}private boolean modernTheme(){return "Modern UI".equals(themeChoice());}
private void appearanceDialog(){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),dp(8),dp(20),dp(4));TextView th=tv("Theme",13);th.setTypeface(null,1);box.addView(th);RadioGroup themes=new RadioGroup(this);RadioButton classic=new RadioButton(this);classic.setText("Classic Retro");RadioButton modern=new RadioButton(this);modern.setText("Modern");themes.addView(classic);themes.addView(modern);if(modernTheme())modern.setChecked(true);else classic.setChecked(true);box.addView(themes);TextView md=tv("Mode",13);md.setTypeface(null,1);md.setPadding(0,dp(14),0,dp(2));box.addView(md);RadioGroup modes=new RadioGroup(this);RadioButton system=new RadioButton(this);system.setText("System");RadioButton light=new RadioButton(this);light.setText("Light");RadioButton dark=new RadioButton(this);dark.setText("Dark");modes.addView(system);modes.addView(light);modes.addView(dark);String cur=getPreferences(0).getString("appearance","System");if("Light".equals(cur))light.setChecked(true);else if("Dark".equals(cur))dark.setChecked(true);else system.setChecked(true);box.addView(modes);new AlertDialog.Builder(this).setTitle("Appearance").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Apply",(d,w)->{String t=modern.isChecked()?"Modern UI":"Classic";String mode=light.isChecked()?"Light":(dark.isChecked()?"Dark":"System");getPreferences(0).edit().putString("theme",t).putString("appearance",mode).putString("restore_tab",currentTab).apply();applyAppearance(mode);recreate();}).show();}
private void applyAppearance(String v){android.content.res.Configuration c=new android.content.res.Configuration(getResources().getConfiguration());int night;if("Dark".equals(v))night=android.content.res.Configuration.UI_MODE_NIGHT_YES;else if("Light".equals(v))night=android.content.res.Configuration.UI_MODE_NIGHT_NO;else{int sys=getApplicationContext().getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK;night=sys;}c.uiMode=(c.uiMode&~android.content.res.Configuration.UI_MODE_NIGHT_MASK)|night;getResources().updateConfiguration(c,getResources().getDisplayMetrics());}
 @Override public void onCreate(Bundle b){super.onCreate(b);applyAppearance(getPreferences(0).getString("appearance","System"));setContentView(R.layout.activity_main);db=new AppDatabase(this);db.cleanup30Days();content=findViewById(R.id.content);title=findViewById(R.id.headerTitle);subtitle=findViewById(R.id.headerSubtitle);bottomNav=findViewById(R.id.bottomNav);accountsButton=findViewById(R.id.accountsButton);accountsButton.setOnClickListener(v->showAccounts());findViewById(R.id.tabRedeem).setOnClickListener(v->showRedeem());findViewById(R.id.tabCodes).setOnClickListener(v->showCodes());findViewById(R.id.tabHistory).setOnClickListener(v->showHistory("ALL"));String restore=getPreferences(0).getString("restore_tab","REDEEM");getPreferences(0).edit().remove("restore_tab").apply();if("CODES".equals(restore))showCodes();else if("HISTORY".equals(restore))showHistory("ALL");else if("ACCOUNTS".equals(restore))showAccounts();else showRedeem();}
 private void shell(String t,String sub,boolean nav,boolean accounts){title.setText(t);subtitle.setText(sub);bottomNav.setVisibility(nav?View.VISIBLE:View.GONE);accountsButton.setVisibility(accounts?View.VISIBLE:View.GONE);if(nav){Button r=findViewById(R.id.tabRedeem),c=findViewById(R.id.tabCodes),h=findViewById(R.id.tabHistory);Button[]bs={r,c,h};for(Button x:bs){x.setBackgroundColor(android.graphics.Color.TRANSPARENT);x.setTextColor(getColor(R.color.muted));}Button active="CODES".equals(currentTab)?c:("HISTORY".equals(currentTab)?h:r);active.setBackgroundResource(R.drawable.nav_selected);active.setTextColor(getColor(R.color.primary));}}
 private void showRedeem(){currentTab="REDEEM";shell("WOS Gift Redeemer",db.selectedAccounts().size()+" accounts selected",true,true);LinearLayout b=body();List<Account>a=db.accounts();if(a.isEmpty()){LinearLayout c=card();heading(c,"Add your first account","Add a WOS Player ID and State before redeeming gift codes.");Button add=btn("Add Account");add.setOnClickListener(v->accountForm(null));c.addView(add);b.addView(c);setPage(page(b));return;}if(db.selectedAccounts().isEmpty()){LinearLayout c=card();heading(c,"No accounts selected","Choose at least one account before starting redemption.");Button x=btn("Select Accounts");x.setOnClickListener(v->showAccounts());c.addView(x);b.addView(c);setPage(page(b));return;}
  LinearLayout fresh=card();heading(fresh,"Check New Codes","Find currently active codes and redeem this fetched batch for selected accounts.");Button check=btn("Check New Codes");check.setOnClickListener(v->fetchForRedeem());fresh.addView(check);b.addView(fresh);
  TextView or=tv("Saved Codes",14);or.setTypeface(null,1);or.setTextColor(getColor(R.color.muted));b.addView(or);LinearLayout saved=card();TextView choice=tv("Latest 5",17);choice.setTypeface(null,1);saved.addView(choice);Button choose=btn("Choose Code Range");choose.setOnClickListener(v->rangeDialog(choice));saved.addView(choose);CheckBox retry=new CheckBox(this);retry.setText("Retry previously attempted pairs");saved.addView(retry);Button run=btn("Redeem Saved Codes");run.setOnClickListener(v->{Object tag=choice.getTag();int count=tag instanceof Integer?(Integer)tag:5;startSavedRun(count,retry.isChecked());});saved.addView(run);TextView count=tv(db.codeCount()+" saved code(s)",12);count.setTextColor(getColor(R.color.muted));saved.addView(count);b.addView(saved);setPage(page(b));}
 private void rangeDialog(TextView target){String[] items={"Latest 5","Latest 10","Custom","All saved codes","Choose individually"};new AlertDialog.Builder(this).setTitle("Redeem saved codes").setItems(items,(d,w)->{if(w==0){target.setText(items[w]);target.setTag(5);}else if(w==1){target.setText(items[w]);target.setTag(10);}else if(w==2)customCount(target);else if(w==3){target.setText(items[w]);target.setTag(0);}else showCodesSelection();}).show();}
 private void customCount(TextView target){EditText e=new EditText(this);e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setHint("Number of latest codes");AlertDialog d=new AlertDialog.Builder(this).setTitle("Custom number of codes").setMessage("Codes are selected newest first.").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{try{int n=Integer.parseInt(e.getText().toString().trim());if(n<1)throw new Exception();target.setText("Latest "+n);target.setTag(n);d.dismiss();}catch(Exception z){e.setError("Enter 1 or more");}}));d.show();}
 private void fetchForRedeem(){if(busy)return;shell("Checking for codes","Looking for currently active WOS gift codes...",false,false);LinearLayout b=body();LinearLayout c=card();heading(c,"Checking for new codes...","This usually takes a few seconds.");ProgressBar p=new ProgressBar(this);c.addView(p);b.addView(c);setPage(page(b));busy=true;scraper=new GiftCodeScraper(this);scraper.fetch(new GiftCodeScraper.Callback(){public void success(List<String>x){busy=false;db.saveFetchedCodes(x);db.cleanup30Days();showFetchedBatch(x);}public void error(String m){busy=false;showFetchError(m);}});}
 private void showFetchedBatch(List<String> raw){LinkedHashSet<String>set=new LinkedHashSet<>();for(String s:raw)if(s!=null&&!s.trim().isEmpty())set.add(s.trim());List<String>codes=new ArrayList<>(set);shell("New Codes",codes.size()+" active code(s) found",false,false);LinearLayout b=body();if(codes.isEmpty()){LinearLayout c=card();heading(c,"No active codes found","The page loaded successfully, but no active codes were found.");Button done=btn("Done");done.setOnClickListener(v->showRedeem());c.addView(done);b.addView(c);setPage(page(b));return;}LinearLayout c=card();heading(c,codes.size()+" active codes found","This redemption uses only the codes from this fetch.");for(String code:codes)c.addView(tv(""+code,15));TextView calc=tv(codes.size()+" codes x "+db.selectedAccounts().size()+" accounts",13);calc.setTextColor(getColor(R.color.muted));c.addView(calc);Button run=btn("Redeem "+codes.size()+" Codes");run.setOnClickListener(v->startRun(codes,false,"FETCHED"));c.addView(run);Button done=btn("Save Only / Done");done.setOnClickListener(v->showRedeem());c.addView(done);b.addView(c);setPage(page(b));}
 private void showFetchError(String m){shell("Couldn't check codes","Connection or page-reading problem",false,false);LinearLayout b=body(),c=card();heading(c,"Couldn't check codes","We couldn't load the current gift-code list.");Button retry=btn("Try Again");retry.setOnClickListener(v->fetchForRedeem());c.addView(retry);Button details=btn("View Details");details.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Technical details").setMessage(m).setPositiveButton("OK",null).show());c.addView(details);Button back=btn("Back");back.setOnClickListener(v->showRedeem());c.addView(back);b.addView(c);setPage(page(b));}
 private void startSavedRun(int count,boolean retry){List<AppDatabase.CodeRow>rows=db.codes(count,null);if(rows.isEmpty()){Toast.makeText(this,"No saved codes",Toast.LENGTH_SHORT).show();return;}List<String>x=new ArrayList<>();for(AppDatabase.CodeRow r:rows)x.add(r.code);confirmRun(x,retry,"SAVED");}
 private void confirmRun(List<String>codes,boolean retry,String source){int accounts=db.selectedAccounts().size();new AlertDialog.Builder(this).setTitle("Ready to Redeem").setMessage(codes.size()+" codes\n"+accounts+" accounts\n\nUp to "+(codes.size()*accounts)+" redemption attempts"+(retry?"\n\nRetry mode is enabled.":"\n\nPreviously completed combinations will be skipped.")).setNegativeButton("Cancel",null).setPositiveButton("Start",(d,w)->startRun(codes,retry,source)).show();}
 private void startRun(List<String>codes,boolean retry,String source){List<Account>accounts=db.selectedAccounts();if(accounts.isEmpty()){showAccounts();return;}busy=true;cancelRequested=false;long runId=db.createRun(source);shell("Redeeming",codes.size()+" codes / "+accounts.size()+" accounts",false,false);LinearLayout b=body(),c=card();TextView progressText=tv("0 of "+(codes.size()*accounts.size()),18);progressText.setTypeface(null,1);c.addView(progressText);ProgressBar p=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);p.setMax(codes.size()*accounts.size());c.addView(p);TextView current=tv("Preparing...",15);c.addView(current);TextView counts=tv("Success 0   /   Received 0   /   Failed 0   /   Connection 0",13);counts.setTextColor(getColor(R.color.muted));c.addView(counts);Button cancel=btn("Cancel");cancel.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Stop redemption?").setMessage("Completed attempts will remain saved.").setNegativeButton("Keep Running",null).setPositiveButton("Stop",(d,w)->cancelRequested=true).show());c.addView(cancel);b.addView(c);setPage(page(b));worker.execute(()->{int done=0,s=0,r=0,f=0,n=0,k=0;outer:for(String code:codes)for(Account a:accounts){if(cancelRequested)break outer;if(!retry&&db.wasAttempted(a.playerId,a.state,code)){k++;done++;db.record(runId,a,code,"SKIPPED",null,"Previously attempted",null);updateProgress(p,progressText,current,counts,done,codes.size()*accounts.size(),a,code,s,r,f,n,k,"Skipped");continue;}try{JSONObject o=WosRedeemer.redeem(a.playerId,a.state,code);int ec=o.has("err_code")?o.optInt("err_code"):Integer.MIN_VALUE;String result=ec==Integer.MIN_VALUE?"API_FAILED":AppDatabase.classify(ec);if("SUCCESS".equals(result))s++;else if("ALREADY_RECEIVED".equals(result))r++;else f++;db.record(runId,a,code,result,ec==Integer.MIN_VALUE?null:ec,o.optString("msg",null),null);}catch(Exception e){n++;db.record(runId,a,code,"NETWORK_ERROR",null,null,e.toString());}done++;updateProgress(p,progressText,current,counts,done,codes.size()*accounts.size(),a,code,s,r,f,n,k,null);try{Thread.sleep(1000);}catch(InterruptedException e){Thread.currentThread().interrupt();cancelRequested=true;break outer;}}db.finishRun(runId,cancelRequested?"CANCELLED":"COMPLETED");db.cleanup30Days();busy=false;runOnUiThread(()->showRunSummary(runId));});}
 private void updateProgress(ProgressBar p,TextView pt,TextView cur,TextView counts,int done,int total,Account a,String code,int s,int r,int f,int n,int k,String extra){runOnUiThread(()->{p.setProgress(done);pt.setText(done+" of "+total);cur.setText("Current\n"+a.label()+" / "+a.playerId+"\n"+code+(extra==null?"":"\n"+extra));counts.setText("Success "+s+"   /   Received "+r+"   /   Failed "+f+"   /   Connection "+n+(k>0?"   /   Skipped "+k:""));});}
 private void showRunSummary(long id){AppDatabase.RunRow r=db.run(id);shell("Redemption complete",r==null?"Run finished":r.total+" recorded attempts",false,false);LinearLayout b=body(),c=card();if(r==null){heading(c,"Finished","The run completed.");}else{String h="CANCELLED".equals(r.status)?"Redemption stopped":((r.failed+r.network)>0?"Completed with issues":"All done");heading(c,h,r.total+" recorded attempts");c.addView(tv("Success                 "+r.success,15));c.addView(tv("Already received        "+r.received,15));c.addView(tv("Failed                  "+r.failed,15));c.addView(tv("Connection problem      "+r.network,15));if(r.skipped>0)c.addView(tv("Skipped                 "+r.skipped,15));Button details=btn("View Results");details.setOnClickListener(v->showRunDetails(id));c.addView(details);Button done=btn("Done");done.setOnClickListener(v->showRedeem());c.addView(done);}b.addView(c);setPage(page(b));}
 private void showAccounts(){currentTab="ACCOUNTS";shell("Accounts",db.selectedAccounts().size()+" selected",false,false);LinearLayout b=body();LinearLayout actions=card();Button add=btn("Add Account");add.setOnClickListener(v->accountForm(null));addStacked(actions,add);Button appearance=btn("Appearance");appearance.setOnClickListener(v->appearanceDialog());addStacked(actions,appearance);LinearLayout row=new LinearLayout(this);row.setPadding(0,dp(4),0,0);Button all=btn("Select All"),clear=btn("Clear");all.setOnClickListener(v->{db.selectAll(true);showAccounts();});clear.setOnClickListener(v->{db.selectAll(false);showAccounts();});row.addView(all,compactLp());row.addView(clear,compactLp());actions.addView(row);b.addView(actions);for(Account a:db.accounts()){LinearLayout c=card();CheckBox cb=new CheckBox(this);cb.setText(a.label()+"\n"+a.playerId+" / State "+a.state);cb.setTextSize(16);cb.setChecked(a.selected);cb.setPadding(0,dp(8),0,dp(8));cb.setOnCheckedChangeListener((x,on)->{db.setSelected(a.id,on);subtitle.setText(db.selectedAccounts().size()+" selected");});c.addView(cb);LinearLayout buttons=new LinearLayout(this);Button edit=btn("Edit"),del=btn("Delete");edit.setOnClickListener(v->accountForm(a));del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Delete account?").setMessage(a.label()).setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{db.deleteAccount(a.id);showAccounts();}).show());buttons.addView(edit,compactLp());buttons.addView(del,compactLp());c.addView(buttons);b.addView(c);}if(db.accounts().isEmpty())b.addView(tv("No accounts yet.",15));Button back=btn("Back to Redeem");back.setOnClickListener(v->showRedeem());b.addView(back);setPage(page(b));}
 private void accountForm(Account a){LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(dp(20),0,dp(20),0);EditText name=new EditText(this),player=new EditText(this),state=new EditText(this);name.setHint("Account name (optional)");player.setHint("Player ID");state.setHint("State");name.setTextColor(getColor(R.color.ink));player.setTextColor(getColor(R.color.ink));state.setTextColor(getColor(R.color.ink));name.setHintTextColor(getColor(R.color.muted));player.setHintTextColor(getColor(R.color.muted));state.setHintTextColor(getColor(R.color.muted));name.setBackgroundResource(modernTheme()?R.drawable.field_modern:R.drawable.field_classic);player.setBackgroundResource(modernTheme()?R.drawable.field_modern:R.drawable.field_classic);state.setBackgroundResource(modernTheme()?R.drawable.field_modern:R.drawable.field_classic);name.setPadding(dp(12),dp(10),dp(12),dp(10));player.setPadding(dp(12),dp(10),dp(12),dp(10));state.setPadding(dp(12),dp(10),dp(12),dp(10));player.setInputType(2);state.setInputType(2);if(a!=null){name.setText(a.name);player.setText(a.playerId);state.setText(a.state);}f.addView(name);f.addView(player);f.addView(state);AlertDialog d=new AlertDialog.Builder(this).setTitle(a==null?"Add Account":"Edit Account").setView(f).setNegativeButton("Cancel",null).setPositiveButton(a==null?"Add Account":"Save",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{String p=player.getText().toString().trim(),s=state.getText().toString().trim();if(p.isEmpty()){player.setError("Player ID is required");return;}if(s.isEmpty()||!s.matches("\\d+")){state.setError("Enter a valid numeric state");return;}if(a==null){if(!db.addAccount(name.getText().toString().trim(),p,s)){player.setError("Account already exists");return;}}else db.updateAccount(a.id,name.getText().toString().trim(),p,s);d.dismiss();showAccounts();}));d.show();}
 private void showCodes(){currentTab="CODES";shell("Gift Codes",db.codeCount()+" saved codes",true,false);LinearLayout b=body(),top=card();EditText search=new EditText(this);search.setHint("Search gift codes");search.setSingleLine(true);search.setTextColor(getColor(R.color.ink));search.setHintTextColor(getColor(R.color.muted));search.setBackgroundResource(modernTheme()?R.drawable.field_modern:R.drawable.field_classic);search.setPadding(dp(12),dp(10),dp(12),dp(10));addStacked(top,search);LinearLayout codeActions=new LinearLayout(this);codeActions.setOrientation(LinearLayout.HORIZONTAL);Button go=btn("Search");go.setOnClickListener(v->renderCodes(search.getText().toString()));codeActions.addView(go,compactLp());Button refresh=btn("Refresh Catalog");refresh.setOnClickListener(v->fetchOnly());codeActions.addView(refresh,compactLp());top.addView(codeActions);b.addView(top);List<AppDatabase.CodeRow>rows=db.codes(0,null);appendCodes(b,rows);setPage(page(b));}
 private void renderCodes(String q){shell("Gift Codes","Search results",true,false);LinearLayout b=body();List<AppDatabase.CodeRow>rows=db.codes(0,q);appendCodes(b,rows);Button back=btn("Back to all codes");back.setOnClickListener(v->showCodes());b.addView(back);setPage(page(b));}
 private void appendCodes(LinearLayout b,List<AppDatabase.CodeRow>rows){if(rows.isEmpty()){LinearLayout e=card();heading(e,"No saved codes yet","Check for active WOS gift codes to build your code library.");Button x=btn("Check Codes");x.setOnClickListener(v->fetchOnly());e.addView(x);b.addView(e);return;}for(AppDatabase.CodeRow r:rows){LinearLayout c=card();TextView code=tv(r.code,16);code.setTypeface(null,1);c.addView(code);TextView meta=tv("Last seen "+pretty(r.lastSeen),12);meta.setTextColor(getColor(R.color.muted));c.addView(meta);c.setOnClickListener(v->showCodeDetails(r.code));b.addView(c);}}
 private void fetchOnly(){if(busy)return;shell("Checking Codes","Updating local catalog...",false,false);LinearLayout b=body(),c=card();c.addView(new ProgressBar(this));c.addView(tv("Checking active codes...",15));b.addView(c);setPage(page(b));busy=true;scraper=new GiftCodeScraper(this);scraper.fetch(new GiftCodeScraper.Callback(){public void success(List<String>x){busy=false;db.saveFetchedCodes(x);db.cleanup30Days();Toast.makeText(MainActivity.this,"Catalog updated",Toast.LENGTH_SHORT).show();showCodes();}public void error(String m){busy=false;showFetchError(m);}});}
 private void showCodeDetails(String code){AppDatabase.CodeRow r=db.code(code);if(r==null){showCodes();return;}shell("Gift Code","Code details",false,false);LinearLayout b=body(),c=card();heading(c,r.code,"ACTIVE");c.addView(tv("First seen   "+pretty(r.firstSeen),13));c.addView(tv("Last seen    "+pretty(r.lastSeen),13));List<AppDatabase.AttemptRow> attempts=db.attemptsForCode(code);c.addView(tv("\nACCOUNT STATUS",12));Set<String>seen=new HashSet<>();for(AppDatabase.AttemptRow a:attempts){String key=a.player+"/"+a.state;if(seen.add(key))c.addView(tv((a.account==null?a.player:a.account)+" / "+label(a.result),14));}Button run=btn("Redeem for Selected Accounts");run.setOnClickListener(v->confirmRun(Collections.singletonList(code),false,"CODE_DETAIL"));c.addView(run);Button back=btn("Back to Codes");back.setOnClickListener(v->showCodes());c.addView(back);b.addView(c);setPage(page(b));}
 private void showCodesSelection(){List<AppDatabase.CodeRow>rows=db.codes(0,null);if(rows.isEmpty()){Toast.makeText(this,"No saved codes",Toast.LENGTH_SHORT).show();return;}String[]names=new String[rows.size()];boolean[]checked=new boolean[rows.size()];for(int i=0;i<rows.size();i++)names[i]=rows.get(i).code;new AlertDialog.Builder(this).setTitle("Choose codes").setMultiChoiceItems(names,checked,(d,w,on)->checked[w]=on).setNegativeButton("Cancel",null).setPositiveButton("Redeem",(d,w)->{List<String>x=new ArrayList<>();for(int i=0;i<rows.size();i++)if(checked[i])x.add(rows.get(i).code);if(!x.isEmpty())confirmRun(x,false,"SAVED");}).show();}
 private void showHistory(String filter){currentTab="HISTORY";shell("History","Rolling 30-day redemption history",true,false);LinearLayout b=body();LinearLayout chips=new LinearLayout(this);Button all=btn("All"),ok=btn("Successful"),issues=btn("Issues");all.setOnClickListener(v->showHistory("ALL"));ok.setOnClickListener(v->showHistory("SUCCESSFUL"));issues.setOnClickListener(v->showHistory("ISSUES"));chips.addView(all,compactLp());chips.addView(ok,compactLp());chips.addView(issues,compactLp());b.addView(chips);List<AppDatabase.RunRow>runs=db.runs(filter,100);if(runs.isEmpty()){LinearLayout e=card();heading(e,"No redemption history","Completed redemption runs will appear here.");Button x=btn("Go to Redeem");x.setOnClickListener(v->showRedeem());e.addView(x);b.addView(e);}for(AppDatabase.RunRow r:runs){LinearLayout c=card();heading(c,pretty(r.started),r.total+" attempts / "+r.source);c.addView(tv("Success "+r.success+"   Received "+r.received+"   Failed "+r.failed+"   Connection "+r.network+(r.skipped>0?"   Skipped "+r.skipped:""),13));c.setOnClickListener(v->showRunDetails(r.id));b.addView(c);}setPage(page(b));}
 private void showRunDetails(long id){AppDatabase.RunRow r=db.run(id);shell("Run Details",r==null?"":pretty(r.started),false,false);LinearLayout b=body();if(r!=null){LinearLayout sum=card();heading(sum,r.total+" attempts",r.source);sum.addView(tv("Success                 "+r.success,14));sum.addView(tv("Already received        "+r.received,14));sum.addView(tv("Failed                  "+r.failed,14));sum.addView(tv("Connection problem      "+r.network,14));if(r.skipped>0)sum.addView(tv("Skipped                 "+r.skipped,14));b.addView(sum);}String last="";for(AppDatabase.AttemptRow a:db.attempts(id)){String who=(a.account==null||a.account.isEmpty()?"Player "+a.player:a.account)+" / "+a.player;if(!who.equals(last)){TextView h=tv(who,16);h.setTypeface(null,1);b.addView(h);last=who;}LinearLayout c=card();c.addView(tv(a.code,15));TextView res=tv(label(a.result),13);res.setTextColor(getColor("NETWORK_ERROR".equals(a.result)||"API_FAILED".equals(a.result)?R.color.danger:R.color.muted));c.addView(res);if(a.serverCode!=null||a.technical!=null){Button details=btn("Details");details.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Technical details").setMessage((a.serverCode==null?"":"Server code: "+a.serverCode+"\n")+(a.message==null?"":a.message+"\n")+(a.technical==null?"":a.technical)).setPositiveButton("OK",null).show());c.addView(details);}b.addView(c);}Button back=btn("Back to History");back.setOnClickListener(v->showHistory("ALL"));b.addView(back);setPage(page(b));}
 private String label(String r){if("SUCCESS".equals(r))return"Success";if("ALREADY_RECEIVED".equals(r))return"Already received";if("API_FAILED".equals(r))return"Failed";if("NETWORK_ERROR".equals(r))return"Connection problem";if("SKIPPED".equals(r))return"Skipped";return r;}private String symbol(String r){return"";}private String pretty(long ms){if(ms<=0)return"Skipped";SimpleDateFormat f=new SimpleDateFormat("dd MMM, hh:mm a",Locale.getDefault());return f.format(new Date(ms));}
 @Override public void onBackPressed(){if(busy){Toast.makeText(this,"Use Cancel to stop the active operation",Toast.LENGTH_SHORT).show();return;}if(bottomNav.getVisibility()!=View.VISIBLE){if("CODES".equals(currentTab))showCodes();else if("HISTORY".equals(currentTab))showHistory("ALL");else showRedeem();}else super.onBackPressed();}
 @Override protected void onDestroy(){if(scraper!=null)scraper.destroy();worker.shutdownNow();db.close();super.onDestroy();}
}
